        search.setPlaceholder("Número, NCF o proveedor...");search.setClearButtonVisible(true);search.setValueChangeMode(ValueChangeMode.LAZY);search.setValueChangeTimeout(350);status.setLabel("Estado");status.setItems(EstadoFacturaProveedor.values());status.setItemLabelGenerator(FacturasProveedoresView::state);status.setEmptySelectionAllowed(true);status.setPlaceholder("Todos");
