    @Override public void beforeEnter(BeforeEnterEvent e){if(!modules.habilitado("COMPRAS")||!can("facturas_proveedores.ver")){Notification.show("No tienes permiso para acceder a esta opción.");e.rerouteTo(DashboardView.class);return;}load();}
    private void configureGrid(){grid.addColumn(FacturaProveedorDto::numeroFactura).setHeader("Factura").setAutoWidth(true);grid.addColumn(FacturaProveedorDto::proveedor).setHeader("Proveedor").setFlexGrow(1);grid.addColumn(x->DATE.format(x.fecha())).setHeader("Fecha").setAutoWidth(true);grid.addColumn(x->DATE.format(x.vencimiento())).setHeader("Vence").setAutoWidth(true);grid.addColumn(x->money(x.total())).setHeader("Total").setAutoWidth(true);grid.addColumn(x->x.moneda()==null?"—":x.moneda()).setHeader("Moneda").setAutoWidth(true);grid.addComponentColumn(x->badge(x.estado())).setHeader("Estado").setAutoWidth(true);grid.addComponentColumn(this::actions).setHeader("Acciones").setAutoWidth(true);grid.setEmptyStateText("No hay facturas de proveedores registradas.");}
    private Component actions(FacturaProveedorDto x){HorizontalLayout h=actions();h.add(new AppActionButton(ActionType.VIEW,ButtonSize.GRID_ACTION,"Ver factura",e->detail(x.id())));if(x.estado()==EstadoFacturaProveedor.DRAFT&&can("facturas_proveedores.editar"))h.add(new AppActionButton(ActionType.EDIT,ButtonSize.GRID_ACTION,"Editar factura",e->form(x.id())));return h;}
    private void load(){try{var r=pagination.currentRequest();var p=service.search(search.getValue(),from.getValue(),to.getValue(),status.getValue(),r.page(),r.size());grid.setItems(p.getContent());pagination.setTotal(p.getTotalElements());}catch(RuntimeException e){error(e,"No fue posible cargar las facturas.");}}
    private void reloadFirst(){pagination.reset();load();}

